        let state = test_state();
        state.library.lock().albums = (0..300)
            .map(|i| album(&format!("Album {i:03}"), "Artist", 2000 + (i % 20)))
            .collect();

        let body = album_list_body(&state, "/api/v1/library/albums?offset=250&limit=999");
        assert_eq!(body["total"], 300);
